pub const _SourceMapData = struct {
    line_offset_wait_group: sync.WaitGroup = .init(),
    line_offset_tasks: []_SourceMapTask = &.{},
    quoted_contents_wait_group: sync.WaitGroup = .init(),
    quoted_contents_tasks: []_SourceMapTask = &.{},

pub fn computeLineOffsets(ctx: *LinkerContext, alloc: std.mem.Allocator, source_index: Index.Int) void {
            _ = debug("Computing LineOffsetTable: {d}", .{ source_index });
            const line_offset_table: *bun.SourceMap.LineOffsetTable.List = (&ctx.graph.files.items(.line_offset_table)[@as(usize, @intCast(source_index))]);
            const source: *const Logger.Source = (&ctx.parse_graph.input_files.items(.source)[@as(usize, @intCast(source_index))]);
            const loader: options.Loader = ctx.parse_graph.input_files.items(.loader)[@as(usize, @intCast(source_index))];
            if ((!loader.canHaveSourceMap())) {
                line_offset_table.* = .{};
                return;
            }
            const approximate_line_count = ctx.graph.ast.items(.approximate_newline_count)[@as(usize, @intCast(source_index))];
            line_offset_table.* = bun.SourceMap.LineOffsetTable.generate(alloc, source.contents, @as(i32, @intCast(@as(u31, @truncate(approximate_line_count)))));
    }

pub fn computeQuotedSourceContents(ctx: *LinkerContext, _: std.mem.Allocator, source_index: Index.Int) void {
            _ = debug("Computing Quoted Source Contents: {d}", .{ source_index });
            const quoted_source_contents = (&ctx.graph.files.items(.quoted_source_contents)[@as(usize, @intCast(source_index))]);
            _ = quoted_source_contents.reset();
            const loader: options.Loader = ctx.parse_graph.input_files.items(.loader)[@as(usize, @intCast(source_index))];
            if ((!loader.canHaveSourceMap())) {
                return;
            }
            const source: *const Logger.Source = (&ctx.parse_graph.input_files.items(.source)[@as(usize, @intCast(source_index))]);
            var mutable = MutableString.initEmpty(bun.default_allocator);
            _ = &mutable;
            _ = bun.handleOom(js_printer.quoteForJSON(source.contents, (&mutable), false));
            var mutableOwned = mutable.toDefaultOwned();
            _ = &mutableOwned;
            quoted_source_contents.* = mutableOwned.toOptional();
    }
    pub const Task = _SourceMapTask;
};

