pub noinline fn link(self: *LinkerContext, bundle: *BundleV2, entry_points: []Index, server_component_boundaries: ServerComponentBoundary.List, reachable: []Index) LinkError![]Chunk {
            _ = try self.load(bundle, entry_points, server_component_boundaries, reachable);
            if ((self.options.source_maps != .none)) {
                _ = self.computeDataForSourceMap((blk: {
                break :blk @as([]Index.Int, @ptrCast(reachable));

}));
            }
            _ = self.processHtmlImportFiles();
            if (comptime FeatureFlags.help_catch_memory_issues) {
                _ = self.checkForMemoryCorruption();
            }
            if (bundle.has_any_top_level_await_modules) {
                const import_records_list: []ImportRecord.List = self.graph.ast.items(.import_records);
                const tla_keywords = self.parse_graph.ast.items(.top_level_await_keyword);
                const tla_checks = self.parse_graph.ast.items(.tla_check);
                const input_files = self.parse_graph.input_files.items(.source);
                const flags: []JSMeta.Flags = self.graph.meta.items(.flags);
                const css_asts = self.graph.ast.items(.css);
                var source_index: u32 = 0;
                _ = &source_index;
                while ((source_index < self.graph.files.len)) : (source_index = (source_index + 1)) {
                    if ((source_index == Index.runtime.get())) {
                        continue;
                    }
                    if ((source_index >= import_records_list.len)) {
                        continue;
