                    if ((css_asts[@as(usize, @intCast(source_index))] != null)) {
                        continue;
                    }
                    const import_records = import_records_list[@as(usize, @intCast(source_index))].slice();
                    _ = try self.validateTLA(source_index, tla_keywords, tla_checks, input_files, import_records, flags, import_records_list);
                }
                _ = try self.graph.propagateAsyncDependencies();
            }
            _ = try self.scanImportsAndExports();
            if (self.log.hasErrors()) {
                return error.BuildFailed;
            }
            if (comptime FeatureFlags.help_catch_memory_issues) {
                _ = self.checkForMemoryCorruption();
            }
            _ = try self.treeShakingAndCodeSplitting();
            if (comptime FeatureFlags.help_catch_memory_issues) {
                _ = self.checkForMemoryCorruption();
            }
            const chunks = try self.computeChunks(bundle.unique_key);
            if (self.log.hasErrors()) {
                return error.BuildFailed;
            }
            if (comptime FeatureFlags.help_catch_memory_issues) {
                _ = self.checkForMemoryCorruption();
            }
            _ = try self.computeCrossChunkDependencies(chunks);
            if (comptime FeatureFlags.help_catch_memory_issues) {
                _ = self.checkForMemoryCorruption();
            }
            _ = self.graph.symbols.followAll();
            return chunks;
    }

