                }
            }
            if (self.graph.meta.items(.resolved_exports)[@as(usize, @intCast(other_id))].get(named_import.alias.?)) |matching_export| {
                _ = &matching_export;
                return .{ .value = .{ .source_index = matching_export.data.source_index, .import_ref = matching_export.data.import_ref, .name_loc = matching_export.data.name_loc }, .status = .found, .import_data = matching_export.potentially_ambiguous_export_star_refs.slice() };
            }
            const is_commonjs_to_esm = flags.force_cjs_to_esm;
            if ((other_kind.isESMWithDynamicFallback() or is_commonjs_to_esm)) {
                return .{ .value = .{ .source_index = Index.source(other_source_index), .import_ref = self.graph.ast.items(.exports_ref)[@as(usize, @intCast(other_id))] }, .status = (if (is_commonjs_to_esm) .dynamic_fallback_interop_default else .dynamic_fallback) };
            }
            const other_loader = self.parse_graph.input_files.items(.loader)[@as(usize, @intCast(other_id))];
            if ((named_import.is_exported and other_loader.isTypeScript())) {
                return .{ .value = .{}, .status = .probably_typescript_type };
            }
