    }

pub fn matchImportsWithExportsForFile(self: *LinkerContext, named_imports_ptr: *JSAst.NamedImports, imports_to_bind: *RefImportData, source_index: Index.Int) void {
            var named_imports = bun.handleOom(named_imports_ptr.clone(self.allocator()));
            _ = &named_imports;
            defer {
            named_imports_ptr.* = named_imports;
            }
            const Sorter = _NamedImportsSorter;
            const sorter = Sorter{ .imports = (&named_imports) };
            _ = named_imports.sort(sorter);
            var _ni_i: usize = 0;
            _ = &_ni_i;
            for (cp_iter_slice(named_imports.keys())) |sym_ref_item| {
                _ = &sym_ref_item;
                const named_import = named_imports.values()[@as(usize, @intCast(_ni_i))];
                _ni_i = (_ni_i + 1);
                _ = self.cycle_detector.clearRetainingCapacity();
                const import_ref = sym_ref_item;
                var re_exports = std.array_list.Managed(js_ast.Dependency).init(self.allocator());
                _ = &re_exports;
                const result = self.matchImportWithExport(.{ .source_index = Index.source(source_index), .import_ref = import_ref }, (&re_exports));
                switch (result.kind) {
.normal => {
_ = ((imports_to_bind.put(self.allocator(), import_ref, .{ .re_exports = bun.BabyList(js_ast.Dependency).fromOwnedSlice(re_exports.items), .data = .{ .source_index = Index.source(result.source_index), .import_ref = result.ref } })) catch unreachable);
},
.namespace => {
(self.graph.symbols.get(import_ref)).?.namespace_alias = js_ast.G.NamespaceAlias{ .namespace_ref = result.namespace_ref, .alias = result.alias };
},
.normal_and_namespace => {
_ = ((imports_to_bind.put(self.allocator(), import_ref, .{ .re_exports = bun.BabyList(js_ast.Dependency).fromOwnedSlice(re_exports.items), .data = .{ .source_index = Index.source(result.source_index), .import_ref = result.ref } })) catch unreachable);
                (self.graph.symbols.get(import_ref)).?.namespace_alias = js_ast.G.NamespaceAlias{ .namespace_ref = result.namespace_ref, .alias = result.alias };
},
.cycle => {
const source = (&self.parse_graph.input_files.items(.source)[@as(usize, @intCast(source_index))]);
                const r = lex.rangeOfIdentifier(source, ((named_import.alias_loc) orelse (Logger.Loc.Empty)));
                _ = ((self.log.addRangeErrorFmt(source, r, self.allocator(), "Detected cycle while resolving import \"{s}\"", .{ named_import.alias.? })) catch unreachable);
},
.probably_typescript_type => {
_ = ((self.graph.meta.items(.probably_typescript_type)[@as(usize, @intCast(source_index))].put(self.allocator(), import_ref, undefined)) catch unreachable);
},
.ambiguous => {
const source = (&self.parse_graph.input_files.items(.source)[@as(usize, @intCast(source_index))]);
                const r = lex.rangeOfIdentifier(source, ((named_import.alias_loc) orelse (Logger.Loc.Empty)));
                const symbol: *Symbol = (self.graph.symbols.get(import_ref)).?;
                if ((symbol.import_item_status == .generated)) {
                    symbol.import_item_status = .missing;
                    _ = ((self.log.addRangeWarningFmt(source, r, self.allocator(), "Import \"{s}\" will always be undefined because there are multiple matching exports", .{ named_import.alias.? })) catch unreachable);
                } else {
                    _ = ((self.log.addRangeErrorFmt(source, r, self.allocator(), "Ambiguous import \"{s}\" has multiple matching exports", .{ named_import.alias.? })) catch unreachable);
                }
},
.ignore => {

},
}
            }
    }

